const item = $input.item.json;
const SUPABASE_URL = 'https://uzghfpxboktnbcbbthns.supabase.co'.replace(/\/$/, '');
const SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY;
const N8N_BASE_URL = 'https://n8n.srv1649259.hstgr.cloud';

const VALID_STYLES = ['scandinavian','japandi','midcentury','traditional','industrial','boho'];
const VALID_ROOMS  = ['bedroom','kids room','dining room','kitchen','mandir','living room'];

function errResult(error, phase, detail) {
  return [{ json: { file_index: item.file_index ?? 0, status: 'error', error, phase, detail: detail || null } }];
}

// n8n task-runner sandbox blocks require('crypto')
function sandboxUuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// 1. Validate inputs
const { file_b64, file_mime, filename, style_tag, room_type, user_id, bearer_token } = item;
let _jwt = String(bearer_token || '').trim();
while (/^Bearer\s+/i.test(_jwt)) _jwt = _jwt.replace(/^Bearer\s+/i, '').trim();
const bearerHeader = _jwt ? `Bearer ${_jwt}` : '';
const file_index = item.file_index ?? 0;

if (!file_b64) return errResult('missing_file_b64', 'validate');
if (!VALID_STYLES.includes(style_tag)) return errResult(`invalid_style_tag: ${style_tag}`, 'validate');
if (!VALID_ROOMS.includes(room_type))  return errResult(`invalid_room_type: ${room_type}`, 'validate');
if (!file_mime || !file_mime.startsWith('image/')) return errResult('invalid_mime_type', 'validate');
if (!user_id || !bearer_token) return errResult('missing_user_credentials', 'validate');

const b64Bytes = Math.floor(file_b64.length * 3 / 4);
if (b64Bytes > 10 * 1024 * 1024) return errResult('file_too_large_max_10mb', 'validate');

// 2. Prepare storage path
const ext = file_mime === 'image/png' ? 'png' : file_mime === 'image/webp' ? 'webp' : 'jpg';
const uuid = sandboxUuid();
const storage_path = `studio/${user_id}/${style_tag}/${room_type}/${uuid}.${ext}`;
const source_url   = `${SUPABASE_URL}/storage/v1/object/reference-images/${storage_path}`;

// 3. Upload binary to Supabase Storage (service key — server-side)
const binary = Buffer.from(file_b64, 'base64');
let uploadResp;
try {
  uploadResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/storage/v1/object/reference-images/${storage_path}`,
    headers: { 'apikey': SERVICE_KEY, 'Authorization': `Bearer ${SERVICE_KEY}`, 'Content-Type': file_mime, 'x-upsert': 'false' },
    body: binary,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  return errResult('storage_upload_exception', 'storage', e.message);
}
if (uploadResp.statusCode !== 200) {
  return errResult('storage_upload_failed', 'storage', uploadResp.body);
}

// Helper: delete storage object (compensating action on later failures)
async function deleteStorage() {
  try {
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${SUPABASE_URL}/storage/v1/object/reference-images/${storage_path}`,
      headers: { 'Authorization': `Bearer ${SERVICE_KEY}`, 'apikey': SERVICE_KEY },
      ignoreHttpStatusErrors: true,
    });
  } catch(_) {}
}

// 4. Get 5-min signed URL for the captioner to fetch the image
let signResp;
try {
  signResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/storage/v1/object/sign/reference-images/${storage_path}`,
    headers: { 'Authorization': `Bearer ${SERVICE_KEY}`, 'apikey': SERVICE_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ expiresIn: 300 }),
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  await deleteStorage.call(this);
  return errResult('signed_url_exception', 'storage', e.message);
}
const signedPath = signResp.signedURL || signResp.signedUrl || signResp.signed_url;
if (!signedPath) {
  await deleteStorage.call(this);
  return errResult('signed_url_missing', 'storage', signResp);
}
const signed_url = signedPath.startsWith('http')
  ? (signedPath.includes('/storage/v1/object/sign/') ? signedPath : signedPath.replace('/object/sign/', '/storage/v1/object/sign/'))
  : `${SUPABASE_URL}/storage/v1${signedPath.startsWith('/') ? signedPath : '/' + signedPath}`;

// 5. Call caption_generate webhook
let captionResp;
try {
  captionResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${N8N_BASE_URL}/webhook/caption/generate`,
    headers: { 'Authorization': bearerHeader, 'Content-Type': 'application/json' },
    body: JSON.stringify({ image_url: signed_url, style_tag, room_type }),
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  await deleteStorage.call(this);
  return errResult('caption_exception', 'caption', e.message);
}
if (captionResp.statusCode !== 200) {
  await deleteStorage.call(this);
  return errResult('caption_failed', 'caption', captionResp.body);
}
const captionBody = captionResp.body;
if (captionBody.error || !captionBody.caption) {
  await deleteStorage.call(this);
  return errResult('caption_parse_error', 'caption', captionBody);
}
const { caption, spatial_signature } = captionBody;

// 6. Insert reference_images row using user's bearer (RLS enforces owner_id)
let insertResp;
try {
  insertResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/reference_images`,
    headers: {
      'Authorization': `Bearer ${SERVICE_KEY}`,
      'apikey': SERVICE_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: JSON.stringify({
      owner_id: user_id,
      source: 'studio',
      source_id: uuid,
      source_url,
      license: 'owned',
      storage_path,
      caption,
      spatial_signature,
      room_type,
      style_tags: [style_tag],
    }),
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  await deleteStorage.call(this);
  return errResult('insert_exception', 'database', e.message);
}
if (insertResp.statusCode !== 201) {
  await deleteStorage.call(this);
  return errResult('insert_failed', 'database', insertResp.body);
}

const inserted = Array.isArray(insertResp.body) ? insertResp.body[0] : insertResp.body;
return [{ json: {
  file_index,
  status: 'ok',
  id: inserted.id,
  source_url,
  storage_path,
  caption_preview: caption.slice(0, 200),
} }];

const prev = $input.item.json;
if (prev.status === 'error') return [{ json: prev }];

const SUPABASE_URL = 'https://uzghfpxboktnbcbbthns.supabase.co'.replace(/\/$/, '');
const SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY;
const OR_KEY = process.env.OPENROUTER_API_KEY;

const MOOD_VOCAB = ['cozy','minimal','dramatic','airy','warm','cool',
                   'dark','bright','eclectic','serene','bold','rustic',
                   'luxurious','playful'];

// Download image using service key (works regardless of bucket policy)
let b64, mime = 'image/jpeg';
try {
  const raw = await this.helpers.httpRequest({
    method: 'GET',
    url: prev.source_url,
    headers: { 'Authorization': `Bearer ${SERVICE_KEY}`, 'apikey': SERVICE_KEY },
    encoding: 'arraybuffer',
    ignoreHttpStatusErrors: true,
  });
  b64 = Buffer.from(raw).toString('base64');
} catch (_) {
  return [{ json: { ...prev, enhance_error: 'fetch_failed' } }];
}

const prompt = `Analyse this interior design image. Return ONLY valid JSON (no markdown, no code fences):\n{\n  "caption_enhanced": "<3-4 sentence description covering visual style, spatial structure, materials, mood>",\n  "spatial_signature": {\n    "room_shape": "rectangular|square|L-shaped|open-plan",\n    "depth_cues": "strong|moderate|minimal",\n    "ceiling_height": "low|standard|high|vaulted",\n    "window_wall": "left|right|back|front|multiple|none",\n    "light_direction": "front-left|front-right|back-left|back-right|overhead|diffuse",\n    "focal_wall": "front|left|right|ceiling",\n    "floor_visible_pct": <integer 0-100>,\n    "symmetry": "symmetric|asymmetric|partial",\n    "open_to": []\n  },\n  "mood_tags": [<2-4 tags chosen from: ${MOOD_VOCAB.join(', ')}>]\n}`;

let orBody;
try {
  orBody = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { 'Authorization': `Bearer ${OR_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'google/gemini-2.5-flash',
      messages: [{ role: 'user', content: [
        { type: 'text', text: prompt },
        { type: 'image_url', image_url: { url: `data:${mime};base64,${b64}` } }
      ]}],
      temperature: 0.2,
      max_tokens: 700,
    }),
    ignoreHttpStatusErrors: true,
  });
} catch (_) {
  return [{ json: { ...prev, enhance_error: 'llm_failed' } }];
}

let caption_enhanced = null, spatial_signature = null, mood_tags = [];
try {
  const content = orBody?.choices?.[0]?.message?.content || '';
  const m = content.match(/\{[\s\S]*\}/);
  if (m) {
    const p = JSON.parse(m[0]);
    caption_enhanced = typeof p.caption_enhanced === 'string' ? p.caption_enhanced : null;
    spatial_signature = p.spatial_signature && typeof p.spatial_signature === 'object' ? p.spatial_signature : null;
    mood_tags = Array.isArray(p.mood_tags) ? p.mood_tags.filter(t => MOOD_VOCAB.includes(t)).slice(0, 4) : [];
  }
} catch (_) {}

// PATCH DB row — best-effort, never block the upload response
if (caption_enhanced && prev.id) {
  const patch = { caption_enhanced, mood_tags, caption_enhanced_at: new Date().toISOString() };
  if (spatial_signature) patch.spatial_signature = spatial_signature;
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/reference_images?id=eq.${prev.id}`,
      headers: {
        'Authorization': `Bearer ${SERVICE_KEY}`,
        'apikey': SERVICE_KEY,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal',
      },
      body: JSON.stringify(patch),
      ignoreHttpStatusErrors: true,
    });
  } catch (_) {}
}

return [{ json: {
  ...prev,
  mood_tags,
  caption_enhanced_preview: caption_enhanced ? caption_enhanced.slice(0, 100) : null,
} }];
